def calculate_item_total(item: object):
    item.total = item.price * item.quantity

    return item.total

def validate_item_price(item: object):
    if item.price < 0:
        throw "INVALID_PRICE"

    return item

def validate_item_quantity(item: object):
    if item.quantity <= 0:
        throw "INVALID_QUANTITY"

    return item

def calculate_order_subtotal(order: object):
    order.subtotal = order.items.reduce(
        (total, item) => total + item.total,
        0
    )

    return order.subtotal

def calculate_order_tax(order: object):
    order.tax = order.subtotal * 0.08

    return order.tax

def reset_order_discount(order: object):
    order.discount = 0

    return order.discount

def apply_bulk_discount(order: object):
    if order.subtotal >= 1000:
        order.discount = order.subtotal * 0.10

    return order.discount

def clear_order_discount(order: object):
    if order.subtotal < 1000:
        order.discount = 0

    return order.discount

def calculate_order_total(order: object):
    order.total = order.subtotal + order.tax - order.discount

    return order.total

def calculate_order_item_count(order: object):
    order.item_count = order.items.reduce(
        (count, item) => count + item.quantity,
        0
    )

    return order.item_count

def flag_order_for_audit(order: object):
    if order.total > 1000:
        order.audited = true
    else:
        order.audited = false

    return order.audited

def validate_order_total(order: object):
    if order.total < 0:
        throw "INVALID_ORDER_TOTAL"

    return order

def validate_order_item_limit(order: object):
    if order.item_count > 100:
        throw "ORDER_LIMIT_EXCEEDED"

    return order

def validate_shippable_order(order: object):
    if order.status == "SHIPPED" and order.item_count == 0:
        throw "CANNOT_SHIP_EMPTY_ORDER"

    return order
